/* ===== iMessage iOS 26 风格顶栏 ===== */

.chat-detail-screen .chat-header-custom {
    position: absolute !important;
    top: 0 !important;
    left: 0 !important;
    right: 0 !important;
    z-index: 10 !important;
    background: transparent !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    border-bottom: none !important;
    box-shadow: none !important;
    height: auto !important;
    min-height: 90px !important;
    align-items: flex-start !important;
    padding-top: max(var(--nuo-safe-top), 12px) !important;
    padding-left: 12px !important;
    padding-right: 12px !important;
    padding-bottom: 8px !important;
    overflow: visible !important;
}

.chat-detail-screen .chat-header-custom::before {
    content: "" !important;
    position: absolute !important;
    top: 0 !important;
    left: 0 !important;
    right: 0 !important;
    bottom: 0 !important;
    z-index: -1 !important;
    pointer-events: none !important;
    backdrop-filter: blur(8px) saturate(130%) !important;
    -webkit-backdrop-filter: blur(8px) saturate(130%) !important;
    background: linear-gradient(to bottom, 
        rgba(255, 255, 255, 0.08) 0%, 
        rgba(255, 255, 255, 0.05) 40%, 
        rgba(255, 255, 255, 0.02) 75%, 
        transparent 100%) !important;
    mask-image: linear-gradient(to bottom, 
        black 0%, 
        black 50%, 
        rgba(0,0,0,0.6) 75%, 
        transparent 100%) !important;
    -webkit-mask-image: linear-gradient(to bottom, 
        black 0%, 
        black 50%, 
        rgba(0,0,0,0.6) 75%, 
        transparent 100%) !important;
}

.chat-detail-screen .chat-header-custom::after {
    content: "" !important;
    position: absolute !important;
    top: -30px !important;
    left: 0 !important;
    right: 0 !important;
    bottom: -20px !important;
    pointer-events: none !important;
    z-index: -2 !important;
    background: transparent !important;
    backdrop-filter: blur(14px) saturate(140%) !important;
    -webkit-backdrop-filter: blur(14px) saturate(140%) !important;
    mask-image: linear-gradient(to bottom, 
        rgba(0,0,0,0.4) 0%, 
        rgba(0,0,0,0.25) 40%, 
        rgba(0,0,0,0.1) 70%, 
        transparent 100%) !important;
    -webkit-mask-image: linear-gradient(to bottom, 
        rgba(0,0,0,0.4) 0%, 
        rgba(0,0,0,0.25) 40%, 
        rgba(0,0,0,0.1) 70%, 
        transparent 100%) !important;
}

.chat-message-list-custom {
    padding-top: calc(max(var(--nuo-safe-top), 12px) + 78px) !important;
    padding-bottom: calc(80px + var(--nuo-safe-bottom)) !important;
}

